export default function LoadingItau({ isOpen = true }) {
    const [dotCount, setDotCount] = useState(0);

    useEffect(() => {
        if (!isOpen) return undefined;

        const timer = window.setInterval(() => {
            setDotCount((prev) => (prev >= 3 ? 0 : prev + 1));
        }, ITAU_LOADING_DOT_INTERVAL_MS);

        return () => window.clearInterval(timer);
    }, [isOpen]);

    if (!isOpen) return null;

    return (
        <>
            <style>
                {`
                .itau-loading-overlay {
                    position: fixed;
                    top: 0;
                    left: 0;
                    width: 100vw;
                    height: 100vh;
                    background-color: rgba(255, 255, 255, 0.95);
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    z-index: 9999;
                    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                }

                .itau-loading-container {
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    padding: 40px;
                    border-radius: 20px;
                    transition: all 0.3s ease;
                    overflow: visible;
                }

                .itau-loading-animation {
                    width: 800px;
                    height: 800px;
                }

                .itau-loading-text {
                    position: relative;
                    z-index: 1;
                    display: inline-flex;
                    align-items: baseline;
                    justify-content: center;
                    margin: -170px 0 0;
                    padding: 0;
                    color: #ec7000;
                    font-size: 2.2rem;
                    font-weight: 600;
                    letter-spacing: 0.5px;
                    line-height: 1.2;
                    animation: pulse-itau-loading-text 1.5s infinite;
                }

                .itau-loading-dots {
                    display: inline-flex;
                    align-items: center;
                    gap: 5px;
                    min-width: 26px;
                    margin-left: 4px;
                    vertical-align: baseline;
                }

                .itau-loading-dot {
                    width: 6px;
                    height: 6px;
                    border-radius: 50%;
                    background-color: #ec7000;
                    opacity: 0;
                }

                .itau-loading-dot--visible {
                    opacity: 1;
                }

                @media screen and (max-width: 768px) {
                    .itau-loading-text {
                        font-size: 1rem;
                        margin-top: -120px;
                    }
                }

                @keyframes pulse-itau-loading-text {
                    0% {
                        opacity: 0.7;
                    }

                    50% {
                        opacity: 1;
                    }

                    100% {
                        opacity: 0.7;
                    }
                }
                `}
            </style>
            <div className="itau-loading-overlay">
                <div className="itau-loading-container">
                    <Lottie
                        animationData={itauAnimation}
                        loop={true}
                        autoplay={true}
                        className="itau-loading-animation"
                    />
                    <h3 className="itau-loading-text">
                        <span>Cargando</span>
                        <span className="itau-loading-dots" aria-hidden="true">
                            {[0, 1, 2].map((index) => (
                                <span
                                    key={index}
                                    className={
                                        index < dotCount
                                            ? 'itau-loading-dot itau-loading-dot--visible'
                                            : 'itau-loading-dot'
                                    }
                                />
                            ))}
                        </span>
                    </h3>
                </div>
            </div>
        </>
    );
};


